3	using System;
4	using System.ClientModel;
5	using System.Collections.Generic;
6	using System.Threading;
7	using System.Threading.Tasks;
8	using OpenAI.Audio;
9	
10	namespace Microsoft.SemanticKernel.Connectors.AzureOpenAI;
11	
12	/// <summary>
13	/// Base class for AI clients that provides common functionality for interacting with Azure OpenAI services.
14	/// </summary>
15	internal partial class ClientCore
16	{
17	    /// <summary>
18	    /// Generates an image with the provided configuration.
19	    /// </summary>
20	    /// <param name="prompt">Prompt to generate the image</param>
21	    /// <param name="executionSettings">Text to Audio execution settings for the prompt</param>
22	    /// <param name="cancellationToken">The <see cref="CancellationToken"/> to monitor for cancellation requests. The default is <see cref="CancellationToken.None"/>.</param>
23	    /// <returns>Url of the generated image</returns>
24	    internal async Task<IReadOnlyList<AudioContent>> GetAudioContentsAsync(
25	        string prompt,
26	        PromptExecutionSettings? executionSettings,
27	        CancellationToken cancellationToken)
28	    {
29	        Verify.NotNullOrWhiteSpace(prompt);
30	
31	        OpenAITextToAudioExecutionSettings? audioExecutionSettings = OpenAITextToAudioExecutionSettings.FromExecutionSettings(executionSettings);
32	        var (responseFormat, mimeType) = GetGeneratedSpeechFormatAndMimeType(audioExecutionSettings?.ResponseFormat);
33	        SpeechGenerationOptions options = new()
34	        {
35	            ResponseFormat = responseFormat,
36	            Speed = audioExecutionSettings?.Speed,
37	        };
38	
39	        ClientResult<BinaryData> response = await RunRequestAsync(() => this.Client.GetAudioClient(this.ModelId).GenerateSpeechFromTextAsync(prompt, GetGeneratedSpeechVoice(audioExecutionSettings?.Voice), options, cancellationToken)).ConfigureAwait(false);
40	
41	        return [new AudioContent(response.Value.ToArray(), mimeType)];
42	    }
43	
44	    private static GeneratedSpeechVoice GetGeneratedSpeechVoice(string? voice)
45	        => voice?.ToUpperInvariant() switch
46	        {
47	            "ALLOY" => GeneratedSpeechVoice.Alloy,
48	            "ECHO" => GeneratedSpeechVoice.Echo,
49	            "FABLE" => GeneratedSpeechVoice.Fable,
50	            "ONYX" => GeneratedSpeechVoice.Onyx,
51	            "NOVA" => GeneratedSpeechVoice.Nova,
52	            "SHIMMER" => GeneratedSpeechVoice.Shimmer,
53	            _ => throw new NotSupportedException($"The voice '{voice}' is not supported."),
54	        };
55	
56	    private static (GeneratedSpeechFormat Format, string MimeType) GetGeneratedSpeechFormatAndMimeType(string? format)
57	        => format?.ToUpperInvariant() switch
58	        {
59	            "WAV" => (GeneratedSpeechFormat.Wav, "audio/wav"),
60	            "MP3" => (GeneratedSpeechFormat.Mp3, "audio/mpeg"),
61	            "OPUS" => (GeneratedSpeechFormat.Opus, "audio/opus"),
62	            "FLAC" => (GeneratedSpeechFormat.Flac, "audio/flac"),
63	            "AAC" => (GeneratedSpeechFormat.Aac, "audio/aac"),
64	            "PCM" => (GeneratedSpeechFormat.Pcm, "audio/l16"),
65	            _ => throw new NotSupportedException($"The format '{format}' is not supported.")
66	        };
67	}
