97	        request.Headers.Add("Api-Key", this._apiKey);
98	        request.Headers.Add(HttpHeaderConstant.Names.SemanticKernelVersion, HttpHeaderConstant.Values.GetAssemblyVersion(typeof(AzureOpenAITextToAudioClient)));
99	
100	        try
